import sys
from itertools import combinations

data = sys.stdin.read().split()
n = int(data[0])
coins = [int(v) for v in data[1:1 + n]]
s, k = int(data[1 + n]), int(data[2 + n])
stalls = sorted(int(v) for v in data[3 + n:3 + n + s])

def play(i, j, turn):
    if i > j:
        return 0
    if turn == 0:
        return max(coins[i] + play(i + 1, j, 1), coins[j] + play(i, j - 1, 1))
    return min(play(i + 1, j, 0), play(i, j - 1, 0))

print(play(0, n - 1, 0))
best = 0
for chosen in combinations(stalls, k):
    gap = min(chosen[t + 1] - chosen[t] for t in range(k - 1))
    best = max(best, gap)
print(best)

